/* ============================================================================
   @media print — A4 용지 최적화 출력 스타일 (PDF 검은색 여백 완전 제거 및 100% 순백색 보장)
   ============================================================================ */
@page {
  size: A4 portrait;
  margin: 0 !important;
  background: #ffffff !important;
}

@media print {
  :root {
    color-scheme: light !important;
    --bg-color: #ffffff !important;
    background: #ffffff !important;
    background-color: #ffffff !important;
  }

  @page {
    size: A4 portrait;
    margin: 0 !important;
    background: #ffffff !important;
  }

  *, *::before, *::after {
    -webkit-print-color-adjust: exact !important;
    print-color-adjust: exact !important;
    box-shadow: none !important;
    text-shadow: none !important;
    font-family: 'Noto Sans KR', 'Pretendard', -apple-system, BlinkMacSystemFont, 'Apple SD Gothic Neo', 'Malgun Gothic', '맑은 고딕', sans-serif !important;
  }

  strong, b, h1, h2, h3, h4, th, .a4-header h1, .a4-plan-title, [class*="bold"] {
    font-weight: 700 !important;
  }

  [style*="line-through"], .a4-print-sheet [style*="line-through"] {
    text-decoration: line-through !important;
    text-decoration-thickness: 1px !important;
    text-decoration-skip-ink: none !important;
  }

  html, body, body.theme-light, .theme-light, .theme-dark, #root, .app-container, main, section, .calc-result-section, .a4-sheet-wrapper {
    background: #ffffff !important;
    background-color: #ffffff !important;
    color: #0f172a !important;
    min-height: 0 !important;
    height: auto !important;
    margin: 0 !important;
    padding: 0 !important;
    border: none !important;
    box-shadow: none !important;
    overflow: visible !important;
  }

  .site-nav,
  .site-footer,
  .no-print {
    display: none !important;
  }

  .calc-result-section {
    padding: 0 !important;
    margin: 0 !important;
    background: #ffffff !important;
  }

  .a4-sheet-wrapper {
    padding: 0 !important;
    margin: 0 auto !important;
    display: block !important;
    gap: 0 !important;
    width: 210mm !important;
    background: #ffffff !important;
  }

  .a4-print-sheet {
    width: 210mm !important;
    max-width: 210mm !important;
    min-width: 210mm !important;
    height: 297mm !important;
    min-height: 297mm !important;
    max-height: 297mm !important;
    box-sizing: border-box !important;
    box-shadow: none !important;
    border: none !important;
    border-radius: 0 !important;
    background: #ffffff !important;
    background-color: #ffffff !important;
    color: #0f172a !important;
    padding: 9mm 12mm 9mm 12mm !important;
    display: flex !important;
    flex-direction: column !important;
    justify-content: flex-start !important;
    gap: 0.3rem !important;
    page-break-inside: avoid !important;
    break-inside: avoid !important;
    overflow: hidden !important;
    transform: none !important;
    margin: 0 auto !important;
  }

  .a4-flex-spacer {
    flex: 1 1 auto !important;
    min-height: 0 !important;
  }

  .a4-footer-wrapper {
    margin-top: auto !important;
    width: 100% !important;
    flex-shrink: 0 !important;
    display: flex !important;
    flex-direction: column !important;
    gap: 0.25rem !important;
  }

  .a4-page-break {
    page-break-after: always !important;
    break-after: page !important;
  }

  /* 2번 구독 포함 견적서 1페이지 인쇄 시 상단 고정 & 하단 여백 유지 */
  .a4-print-sheet.a4-page-1 {
    justify-content: flex-start !important;
    gap: 0.35rem !important;
    height: 297mm !important;
    min-height: 0 !important;
    max-height: 297mm !important;
  }

  .a4-page-1 .a4-mixed-unified-container {
    justify-content: flex-start !important;
  }

  .a4-page-2,
  .a4-print-sheet.a4-page-2 {
    page-break-after: avoid !important;
    break-after: avoid !important;
    height: 297mm !important;
    min-height: 0 !important;
    max-height: 297mm !important;
  }

  .a4-header {
    flex-direction: row !important;
    padding-bottom: 0.38rem !important;
  }

  .a4-header-right {
    padding: 0.38rem 0.65rem !important;
    gap: 0.18rem !important;
  }

  .a4-doc-title {
    font-size: 1.24rem !important;
    margin: 0.08rem 0 !important;
    white-space: nowrap !important;
  }

  .a4-doc-subtitle {
    font-size: 0.74rem !important;
    white-space: nowrap !important;
  }

  .a4-product-bar {
